class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        m = max(nums)
        pref = [0] * (m + 1)
        for v in range(nums[0] + 1):
            pref[v] = 1
        for i in range(1, len(nums)):
            for v in range(1, m + 1):
                pref[v] = (pref[v] + pref[v - 1]) % MOD
            d = nums[i] - nums[i - 1]
            new = [0] * (m + 1)
            for v in range(m + 1):
                w = v - d if d > 0 else v
                if 0 <= w <= m:
                    new[v] = pref[w]
            pref = new
        return sum(pref) % MOD

