class Solution {
public:
    int countOfPairs(vector<int>& nums) {
        const long long MOD = 1e9 + 7;
        int m = *max_element(nums.begin(), nums.end());
        vector<long long> pref(m + 1, 0);
        for (int v = 0; v <= nums[0]; v++) pref[v] = 1;
        for (size_t i = 1; i < nums.size(); i++) {
            for (int v = 1; v <= m; v++) pref[v] = (pref[v] + pref[v - 1]) % MOD;
            int d = nums[i] - nums[i - 1];
            vector<long long> nw(m + 1, 0);
            for (int v = 0; v <= m; v++) {
                int w = d > 0 ? v - d : v;
                if (w >= 0 && w <= m) nw[v] = pref[w];
            }
            pref = move(nw);
        }
        long long ans = 0;
        for (long long x : pref) ans = (ans + x) % MOD;
        return (int)ans;
    }
};

