class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        m = max(nums)
        dp = [1 if v <= nums[0] else 0 for v in range(m + 1)]
        for i in range(1, len(nums)):
            d = nums[i] - nums[i - 1]
            ndp = [0] * (m + 1)
            for v in range(m + 1):
                s = 0
                for u in range(min(v, v - d) + 1):
                    if u >= 0:
                        s += dp[u]
                ndp[v] = s % MOD
            dp = ndp
        return sum(dp) % MOD

